lemma mapDomain_le_mapDomain_iff_le._mathlib_ {ι : Type*} {κ : Type*} {α : Type*}
    [AddCommMonoid α] [PartialOrder α] [IsOrderedAddMonoid α] {f : ι → κ} (h : f.Injective)
